  const names = new Set();
  const prefix = `${p}/`;
  for (const f of files) {
    const n = f.replace(/\\/g, '/');
    if (n.startsWith(prefix)) names.add(n.slice(prefix.length).split('/')[0]);
  }
  return names.size ? [...names] : null;
}

export default rule;

