export function provenanceFiles(packDir, io) {
  const dir = `${packDir}/${PROVENANCE_DIR}`;
  const out = new Map();
  for (const name of listFiles(io, dir)) {
    if (!name.endsWith('.md') || name === DECLINED_FILE) continue;
    const file = `${dir}/${name}`;
    const text = io.read(file) ?? '';
    const { entries, errors } = parseEntries(text);
    out.set(idOfFile(name), { file, text, entries, errors, status: elementStatus(entries), empty: text.trim() === '' });
  }
  return out;
}

