// The pack's version rows, newest first, and the version a commit landed in: the row
// naming its pull request, else the earliest version cut on or after its date.
function versionRows(io, pack) {
  return (io.read(`${pack}/VERSIONS.md`) ?? '').split('\n')
    .map((l) => /^\|\s*([^|]+?)\s*\|\s*(\d{4}-\d{2}-\d{2})\s*\|\s*(.*?)\s*\|\s*$/.exec(l))
    .filter(Boolean)
    .map(([, version, date, what]) => ({ version, date, what }));
}
function versionFor(rows, info) {
  const byPr = info.pr && rows.find((r) => r.what.includes(`#${info.pr}`) && !new RegExp(`#${info.pr}\\d`).test(r.what));
  if (byPr) return byPr.version;
  const after = rows.filter((r) => r.date >= info.date);
  return after.length ? after[after.length - 1].version : null;
