+const REFERENCED = /\b(?:Refs|Fixes|Closes|Resolves)\s*:?\s*#(\d+)/gi;
+const PR_AT_END = /\s*\(#(\d+)\)\s*$/;
+const ENTRY_FENCE = /^```entry (\S+)\s*$/;
+const BODY_LINES = 60;
